import{_ as t,o as r,c as s,a2 as a}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Guide utilisateur","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/index.md","filePath":"fr/guide/index.md"}'),o={name:"fr/guide/index.md"};function n(i,e,d,l,c,u){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="guide-utilisateur" tabindex="-1">Guide utilisateur <a class="header-anchor" href="#guide-utilisateur" aria-label="Permalink to &quot;Guide utilisateur&quot;">​</a></h1><p>Nid gère et archive vos boîtes Gmail depuis votre propre serveur (NAS, serveur maison). Ce guide suit l&#39;organisation de l&#39;application : une page par écran.</p><hr><h2 id="les-ecrans" tabindex="-1">Les écrans <a class="header-anchor" href="#les-ecrans" aria-label="Permalink to &quot;Les écrans&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Écran</th><th>Adresse</th><th>À quoi il sert</th></tr></thead><tbody><tr><td><a href="./overview.html"><strong>Vue d&#39;ensemble</strong></a></td><td><code>/overview</code></td><td>État du compte, top encombreurs, suggestions, jobs en cours</td></tr><tr><td><a href="./mails.html"><strong>Mails</strong></a></td><td><code>/mails</code></td><td>Rechercher, sélectionner et traiter vos mails en masse, avec annulation</td></tr><tr><td><a href="./cleanup.html"><strong>Nettoyage</strong></a></td><td><code>/cleanup</code></td><td>Expéditeurs &amp; newsletters, gros mails &amp; pièces jointes</td></tr><tr><td><a href="./rules.html"><strong>Règles &amp; libellés</strong></a></td><td><code>/rules</code></td><td>Règles automatiques, libellés Gmail, modèles</td></tr><tr><td><a href="./archives.html"><strong>Archives</strong></a></td><td><code>/archives</code></td><td>Copie locale sur le NAS : recherche, lecteur, partage, corbeille, rétention</td></tr><tr><td><a href="./activity.html"><strong>Activité</strong></a></td><td><code>/activity</code></td><td>Toutes les tâches lancées, en direct</td></tr><tr><td><a href="./settings.html"><strong>Paramètres</strong></a></td><td><code>/settings/…</code></td><td>Compte, Sécurité, Comptes Gmail, Notifications &amp; webhooks, Données</td></tr><tr><td><a href="./attachments.html"><strong>Pièces jointes</strong></a></td><td><code>/attachments</code></td><td>Liste complète des pièces jointes (depuis la palette ⌘K)</td></tr><tr><td><a href="./notifications.html"><strong>Notifications</strong></a></td><td>cloche + Paramètres</td><td>Notifications in-app, toasts, webhooks</td></tr><tr><td><a href="./admin.html"><strong>Administration</strong></a></td><td><code>/admin</code></td><td>Utilisateurs, réglages de l&#39;instance, audit (admins)</td></tr></tbody></table><p>Nouveau sur Nid ? Commencez par les <a href="./first-steps.html"><strong>Premiers pas</strong></a>.</p><hr><h2 id="se-reperer-dans-l-interface" tabindex="-1">Se repérer dans l&#39;interface <a class="header-anchor" href="#se-reperer-dans-l-interface" aria-label="Permalink to &quot;Se repérer dans l&#39;interface&quot;">​</a></h2><h3 id="sur-ordinateur" tabindex="-1">Sur ordinateur <a class="header-anchor" href="#sur-ordinateur" aria-label="Permalink to &quot;Sur ordinateur&quot;">​</a></h3><ul><li><strong>Barre latérale</strong> à gauche : logo, bouton <strong>Réduire la barre latérale</strong> (<code>Ctrl+B</code> / <code>⌘B</code>), sélecteur <strong>Compte Gmail</strong>, bouton <strong>Rechercher…</strong>, puis les entrées Vue d&#39;ensemble, Mails, Nettoyage, Règles &amp; libellés, Archives, Activité, Paramètres. Les administrateurs ont en plus un groupe <strong>Administration</strong> avec <strong>Admin</strong>.</li><li><strong>Compteurs</strong> à côté des entrées : nombre de mails du compte (Mails), nombre de règles actives (Règles &amp; libellés), « N en cours » (Activité).</li><li><strong>En-tête</strong> : cloche des <a href="./notifications.html">notifications</a> et menu utilisateur (avatar) : <strong>Langue</strong>, <strong>Mode sombre</strong>, <strong>Se déconnecter</strong>.</li></ul><h3 id="sur-mobile" tabindex="-1">Sur mobile <a class="header-anchor" href="#sur-mobile" aria-label="Permalink to &quot;Sur mobile&quot;">​</a></h3><p>L&#39;en-tête garde la cloche et l&#39;avatar ; le menu de l&#39;avatar contient en plus le choix du <strong>Compte Gmail</strong>. Une barre en bas d&#39;écran donne accès à <strong>Accueil</strong> (Vue d&#39;ensemble), <strong>Mails</strong>, <strong>Nettoyage</strong>, <strong>Archives</strong> et <strong>Plus</strong>.</p><p>La page <strong>Plus</strong> regroupe le reste :</p><ul><li><strong>Outils</strong> : Règles &amp; libellés, Activité (avec le nombre de tâches en cours) ;</li><li><strong>Paramètres</strong> : les cinq sections, chacune avec un résumé (« 2FA activée », « 1 action requise », « Import, export »…) ;</li><li><strong>Administration</strong> (admins uniquement) : « Admin de l&#39;instance » ;</li><li>en bas : « Connecté(e) en tant que … » et <strong>Se déconnecter de Nid</strong>.</li></ul><h3 id="palette-de-commandes" tabindex="-1">Palette de commandes <a class="header-anchor" href="#palette-de-commandes" aria-label="Permalink to &quot;Palette de commandes&quot;">​</a></h3><p><code>⌘K</code> (Mac) ou <code>Ctrl+K</code> ouvre la palette « Aller à… » : toutes les pages de la navigation, l&#39;action <strong>Nouvelle règle</strong>, et sous <strong>Autres pages</strong> la page <a href="./attachments.html">Pièces jointes</a>.</p><h3 id="anciennes-adresses" tabindex="-1">Anciennes adresses <a class="header-anchor" href="#anciennes-adresses" aria-label="Permalink to &quot;Anciennes adresses&quot;">​</a></h3><p>Les anciennes pages redirigent vers leur nouvel emplacement : <code>/dashboard</code>, <code>/analytics</code>, <code>/insights</code> → Vue d&#39;ensemble ; <code>/unified</code> → Mails, « Tous les comptes » ; <code>/saved-searches</code> → Mails ; <code>/unsubscribe</code> → Nettoyage ; <code>/expiration</code> → Règles &amp; libellés, onglet Libellés ; <code>/archive</code> → Archives ; <code>/sharing</code> → Archives, onglet Partages ; <code>/jobs</code> → Activité ; <code>/privacy</code> → Paramètres › Compte ; <code>/ops</code> → Paramètres › Données.</p>',18)])])}const h=t(o,[["render",n]]);export{m as __pageData,h as default};
